-- GenDB engine variant Q05-conjunct_permutation: template q05.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  n_name,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue
FROM customer, orders, lineitem, supplier, nation, region
WHERE
  o_orderdate < $2 + INTERVAL '1 YEAR'
  AND o_orderdate >= $2
  AND r_name = $1
  AND n_regionkey = r_regionkey
  AND s_nationkey = n_nationkey
  AND c_nationkey = s_nationkey
  AND l_suppkey = s_suppkey
  AND l_orderkey = o_orderkey
  AND c_custkey = o_custkey
GROUP BY
  n_name
ORDER BY
  revenue DESC
